[
  {
    "id": "90000000-0000-0000-0000-000000000328",
    "title": "Dave Ranney",
    "description": "The public-domain text of Dave Ranney by Dave Ranney, preserved across 9 original sections with extracted Scripture references.",
    "total_days": 32,
    "tags": [
      "knowledge",
